'use strict'
const test = require('node:test')
const assert = require('node:assert/strict')
const fs = require('node:fs')
const path = require('node:path')
const read = p => fs.readFileSync(path.join(__dirname, '../..', p), 'utf8')
const swift = n => read('ios/XDriveIOS/' + n + '.swift')
const local = swift('NativeLocalContinuousGallery')
const unified = swift('NativeUnifiedPhotoGallery')
const map = swift('NativeUnifiedSourcePhotoMap')
const localMap = swift('NativeLocalPhotoMap')
const cloud = swift('NativeServerMediaGallery')
const ownerMap = swift('NativeOwnerMapClusterAlbum')
const shared = swift('NativePhotoWallComponents')
const album = swift('NativePhotoAlbumBrowser')
const transport = swift('NativeServerMediaGalleryTransport')

test('P1-1 local 64-slot virtual page uses the shared sections without changing read or selection', () => {
  assert.match(local, /XDriveIOSNativePhotoWallSectionList\(\s*sections: daySections, density: density/)
  assert.match(local, /items: \{ Array\(page\.items\[\$0\.startIndex\.\.<\$0\.endIndex\]\) \}/)
  assert.match(local, /XDriveIOSNativePhotoDayGroupingPolicy\.sections\(/)
  assert.match(local, /previousCapturedAt: precedingCapturedAt/)
  assert.match(local, /XDriveIOSNativePhotoWallSelectionIndicator\(/)
  assert.match(local, /XDriveIOSNativeVisiblePhotoQueueBadgePolicy/)
  assert.match(local, /onSelect\(candidate, page\)/)
  assert.match(local, /page\.items\.count <= 64|expectedTotal - offset/)
  assert.doesNotMatch(local, /ForEach\(daySections\)/)
})

test('P1-2 same-source place wall restores both directions with scoped bounded cursors', () => {
  assert.match(map, /@State private var windowStarts:/)
  assert.match(map, /@State private var windowIndex = -1/)
  assert.match(map, /private func retreat\(forViewer: Bool = false\)/)
  assert.match(map, /private func retreatNearby\(forViewer: Bool = false\)/)
  assert.match(map, /windowStarts\[windowIndex - 2\]/)
  assert.match(map, /maximumWallSeekPages = maximumPages/)
  assert.match(map, /try Task\.checkCancellation\(\)/)
  assert.match(map, /XDriveIOSNativePhotoOwnerScope\.matches\(login\.owner, owner\)/)
  assert.match(map, /XDriveIOSNativePhotoFingerprintIndex\.isCurrent\(library\)/)
})

test('P1-3 same-place Viewer arrows and 48px filmstrip never navigate by unverified ID', () => {
  assert.match(map, /onUnifiedNavigate: navigateViewer/)
  assert.match(map, /private func navigateViewer\(_ direction: Int\)/)
  assert.match(map, /admitViewerNeighbor\(rows\[target\]\)/)
  assert.match(map, /load\(from: next, forViewer: true\)/)
  assert.match(map, /retreat\(forViewer: true\)/)
  assert.match(map, /native-ios-unified-source-map-viewer-filmstrip/)
  assert.match(map, /frame\(width: 48, height: 48\)/)
  assert.match(map, /choice\.session == session\.session/)
})

test('P1-4 live tap and neighbor admission rechecks PhotoKit and Owner Node', () => {
  assert.match(map, /Button \{ openAfterLiveAdmission\(row\) \}/)
  assert.match(map, /await revalidateCurrentMember\(row\)/)
  assert.match(map, /await reproveCurrentSourcePresence\(row\)/)
  assert.match(map, /PHAsset\.fetchAssets\(/)
  assert.match(map, /match\.matches\(liveCloud\)/)
  assert.match(map, /reader\.currentMapItem\(expectedCloud\)/)
  assert.match(transport, /item\.node\.revision == expected\.node\.revision/)
  assert.match(transport, /item\.contentIdentity == expected\.contentIdentity/)
})

test('P1-5 same-window Viewer return preserves pixel scroll and cross-window uses verified focus', () => {
  assert.match(map, /viewerOpeningID = row\.id/)
  assert.match(map, /viewerOpeningWindow = isNearbyExpansion/)
  assert.match(map, /viewerOpeningID == id && sameWindow/)
  assert.match(map, /xdrivePhotoWallFocusVerifiedTile\(/)
  assert.match(map, /focusedTileID = id/)
  assert.match(map, /filter\(\{ \$0\.id == id \}\)\.count == 1/)
  assert.match(map, /XDriveIOSNativePhotoWallWindowPolicy\.canRestore/)
  assert.match(shared, /func xdrivePhotoWallFocusVerifiedTile/)
})

test('P2-1 loading/error UI shares a presentation-only feedback and source-owned retries', () => {
  assert.match(shared, /struct XDriveIOSNativePhotoWallFeedback: View/)
  assert.match(shared, /retryAccessibilityID: String\? = nil/)
  assert.doesNotMatch(shared, /PHPhotoLibrary|verifiedAuthorization|URLSession|UploadSession/)
  for (const source of [map, localMap, cloud, ownerMap])
    assert.match(source, /XDriveIOSNativePhotoWallFeedback\(/)
  assert.match(ownerMap, /canRetry: !busy && activeOwner && viewing == nil/)
  assert.match(localMap, /canRetry: !busy && phase == \.active/)
})

test('P2-2 density/framing are shared appearance-only preferences, not Owner/PhotoKit identity', () => {
  const screens = [local, unified, map, localMap, ownerMap, cloud, album]
  for (const screen of screens)
    assert.match(screen, /@AppStorage\("xdrive\.ios\.gallery\.photo-wall-density\.v1"\)/)
  assert.match(map, /@AppStorage\("xdrive\.ios\.gallery\.photo-wall-framing\.v1"\)/)
  assert.match(unified, /@AppStorage\("xdrive\.ios\.gallery\.photo-wall-framing\.v1"\)/)
  assert.doesNotMatch(shared, /UserDefaults\.standard|PHAsset\.fetchAssets|verifiedAuthorization\(|UploadSession\(/)
})

test('P2-3 local selection, media badge and backup status retain their original source actions', () => {
  assert.match(local, /XDriveIOSNativePhotoWallSelectionIndicator\(/)
  assert.match(local, /XDriveIOSNativeVisiblePhotoQueueBadgePolicy\s*\.badge\(/)
  assert.match(local, /XDriveIOSNativeSquarePhotoTile\(/)
  assert.match(local, /if selectionMode \{\s*GeometryReader/)
  assert.match(local, /Button\("分享本机原件"\)/)
  assert.match(shared, /struct XDriveIOSNativePhotoWallTileShell/)
  assert.match(shared, /struct XDriveIOSNativePhotoWallMediaBadge/)
  assert.match(map, /XDriveIOSUnifiedPhotoTile\(/)
})
